import {title,colors,createFighter,chooseAttack} from './engine.js';
import {BattleView} from './battle-view.js';
import {BattleAudio} from './battle-audio.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let cache={},roster=[],teams=[[382,384,383],[483,487,484]],arena='stadium',fighters=[],running=false,paused=false,done=false,speed=1,cinematic=!matchMedia('(prefers-reduced-motion: reduce)').matches,sound=false,audio,round=0,runId=0,seed=1,startSeed=1,rng,particles=[],beam=null,rings=[],lastTime=0,elapsed=0,ambienceTime=0,selectSlot=[0,0],filter='featured',limit=60,pickerBusy=false;
const featured=[6,9,3,25,94,149,150,151,249,250,254,257,260,282,373,376,382,383,384,445,448,483,484,487,643,644,646,658,716,717,791,792,800,888,889,890];
const view=new BattleView($('#stage'),setImage),audioEngine=new BattleAudio();
let visualRng=Math.random;
const names={stadium:'INDIGO STADIUM',forest:'VIRIDIAN FOREST',volcano:'CINNABAR CRATER'};
function randomSeed(){return crypto.getRandomValues(new Uint32Array(1))[0]}
function seeded(s){return ()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296}}
function sprite(id,animated=true){return featured.includes(id)?`assets/${id}.${animated?'gif':'png'}`:`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${animated?'other/showdown/':''}${id}.${animated?'gif':'png'}`}
function setImage(img,id,animated){img.dataset.fallback='0';img.onerror=()=>{if(img.dataset.fallback==='0'){img.dataset.fallback='1';img.src=sprite(id,false)}else{img.onerror=null;img.alt=title(roster.find(p=>p.id===id)?.name||'Pokémon')}};img.src=sprite(id,animated)}
async function data(id){if(cache[id])return cache[id];try{const saved=JSON.parse(localStorage.getItem('bt-pokemon-'+id)||'null');if(saved){cache[id]=saved;return saved}}catch{}const r=await fetch(`https://pokeapi.co/api/v2/pokemon/${id}`,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Could not load Pokémon data. Please try again.');const p=await r.json(),d={id:p.id,name:p.name,types:p.types.map(x=>x.type.name),stats:p.stats.map(x=>x.base_stat),moves:p.moves.map(x=>x.move.name)};cache[id]=d;try{localStorage.setItem('bt-pokemon-'+id,JSON.stringify(d))}catch{}return d}
function renderTeams(){teams.forEach((team,t)=>{$('#team-'+(t?'b':'a')).replaceChildren(...team.map((id,s)=>{const b=document.createElement('button');b.className='team-slot';b.disabled=running;b.setAttribute('aria-label',`Replace ${title(cache[id]?.name||'Pokémon')} on Team ${t?'Crimson':'Emerald'}`);const img=document.createElement('img');img.alt='';setImage(img,id,false);const info=document.createElement('span');const strong=document.createElement('strong');strong.textContent=title(cache[id]?.name||roster.find(p=>p.id===id)?.name||'Pokémon');const small=document.createElement('small');small.textContent=cache[id]?.types.join(' / ')||'SELECTED';info.append(strong,small);const edit=document.createElement('span');edit.className='edit';edit.textContent='＋';b.append(img,info,edit);b.onclick=()=>openPicker(t,s);return b}))});}
function saveTeams(){try{localStorage.setItem('bt-teams',JSON.stringify(teams))}catch{}}
function openPicker(t,s){selectSlot=[t,s];filter='featured';limit=60;$('#search').value='';$('#picker-context').textContent=`${t?'CRIMSON':'EMERALD'} / SLOT ${s+1}`;$$('.picker-filters button').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));renderPicker();$('#picker').showModal();$('#search').focus()}
function renderPicker(){const q=$('#search').value.trim().toLowerCase().replaceAll(' ','-').replace('#','');const found=roster.filter(p=>(q||filter==='all'||featured.includes(p.id))&&(!q||p.name.includes(q)||String(p.id)===q));$('#result-count').textContent=`${found.length} Pokémon · ${Math.min(limit,found.length)} shown`;$('#more').hidden=found.length<=limit;$('#pokemon-grid').replaceChildren(...found.slice(0,limit).map(p=>{const b=document.createElement('button');b.className='pokemon-card';b.disabled=pickerBusy;const img=document.createElement('img');img.alt='';img.loading='lazy';setImage(img,p.id,false);const n=document.createElement('strong');n.textContent=title(p.name);const no=document.createElement('small');no.textContent='#'+String(p.id).padStart(4,'0');b.append(img,n,no);b.onclick=async()=>{if(pickerBusy)return;const [t,s]=selectSlot;if(teams[t].includes(p.id)&&teams[t][s]!==p.id){$('#picker-context').textContent='Already on this team';return}pickerBusy=true;b.textContent='Loading…';try{await data(p.id);teams[t][s]=p.id;saveTeams();$('#picker').close();renderTeams();resetPreview()}catch(e){$('#picker-context').textContent='Load failed — check connection';}finally{pickerBusy=false;renderPicker()}};return b}));if(!found.length){const p=document.createElement('p');p.className='picker-error';p.textContent='No Pokémon found. Try another name or number.';$('#pokemon-grid').append(p)}}

function resetPreview(){if(running)return;done=false;$('#result').classList.add('hidden');$('#intro-overlay').classList.remove('hidden');$('#battle-status').textContent='AWAITING CHALLENGERS';$('#playback-label').textContent='Ready when you are';$('#turn').textContent='3 VS 3 / REFERENCE PACE';$('#replay').disabled=true;fighters=teams.flatMap((team,t)=>team.map((id,s)=>createFighter(cache[id],t,s)));view.mount(fighters);}
function log(text,kind=''){const box=$('#log');box.querySelector('.empty-log')?.remove();const entry=document.createElement('div');entry.className='log-entry '+kind;const time=document.createElement('time');time.textContent=String(round).padStart(2,'0');const content=document.createElement('span');content.textContent=text;entry.append(time,content);box.append(entry);box.scrollTop=box.scrollHeight;$('#log-count').textContent=`${box.children.length} EVENTS`;}
function wait(ms,token){return new Promise(resolve=>{let left=ms,last=performance.now();function tick(now){if(token!==runId){resolve(false);return}if(!paused)left-=Math.min(now-last,50)*speed;last=now;if(left<=0)resolve(true);else requestAnimationFrame(tick)}requestAnimationFrame(tick)})}
function lockUI(){renderTeams();$('#shuffle').disabled=running;$$('.arena-option').forEach(b=>b.disabled=running);$('#start').disabled=running;$('#start').firstChild.textContent=running?'BATTLE IN PROGRESS ':'LET THEM BATTLE ';$('#pause').disabled=!running;$('#replay').disabled=running||!done;$('#stop').disabled=!running;}
async function start(replay=false){if(running||!fighters.length)return;runId++;const token=runId;running=true;paused=false;done=false;round=0;elapsed=0;startSeed=replay?startSeed:randomSeed();seed=startSeed;rng=seeded(seed);visualRng=seeded(seed^0x5121);fighters=teams.flatMap((team,t)=>team.map((id,s)=>createFighter(cache[id],t,s)));view.mount(fighters);$('#stage').classList.remove('paused');$('#pause').innerHTML='Ⅱ <span>Pause</span>';$('#intro-overlay').classList.add('hidden');$('#result').classList.add('hidden');$('#log').replaceChildren();$('#battle-status').textContent='BATTLE LIVE';$('#playback-label').textContent='The showdown is live';lockUI();log('The challengers enter the arena. Let the battle begin!');audioEngine.background(true);audioEngine.cry(fighters[1].id,featured.includes(fighters[1].id));view.message('FIGHT!',750,true);await wait(800,token);
while(token===runId&&fighters.some(p=>p.team===0&&p.hp>0)&&fighters.some(p=>p.team===1&&p.hp>0)&&round<180){round++;$('#turn').textContent=`TURN ${String(round).padStart(2,'0')} · ${fighters.filter(p=>p.hp>0).length} REMAIN`;const attack=chooseAttack(fighters,rng);if(!attack)break;await animateAttack(attack,token);if(!await wait(180,token))return;}
if(token!==runId)return;running=false;done=true;view.label=null;const a=fighters.filter(p=>p.team===0&&p.hp>0),b=fighters.filter(p=>p.team===1&&p.hp>0),winner=!a.length?1:!b.length?0:null;const name=winner===null?'':view.teamName(winner);$('#result h2').textContent=winner!==null?name+' WINS!':'A LEGENDARY STALEMATE';$('#result p').textContent=winner!==null?`${(winner===0?a:b).map(p=>title(p.name)).join(', ')} ${(winner===0?a:b).length===1?'stands':'stand'} victorious!`:'Neither team fell after 180 turns. Try a new matchup.';$('#result-stats').textContent=`${round} TURNS · ${Math.round(elapsed)}s · SEED ${startSeed}`;$('#result').classList.remove('hidden');$('#battle-status').textContent='BATTLE COMPLETE';$('#playback-label').textContent=winner!==null?name+' takes the arena':'An evenly matched showdown';log(winner!==null?name+' wins!':'The battle ends in a draw.','ko');if(winner!==null)audioEngine.cry((winner===0?a:b)[0].id,featured.includes((winner===0?a:b)[0].id));audioEngine.background(false);lockUI();}
async function animateAttack(a,token){const {actor,target,move,damage,mult,crit,dodge}=a,c=colors[move.type],source={...actor.pos},dest={...target.pos},w=ms=>wait(ms,token),dx=dest.x-source.x,dy=dest.y-source.y,distance=Math.hypot(dx,dy),nx=dx/distance,ny=dy/distance,physical=move.category==='physical'&&!['ground','meteor','burst'].includes(move.fx),asset={fire:'fireball',water:'waterwisp',electric:'electroball',grass:'energyball',ice:'iceball',ghost:'shadowball',psychic:'shadowball',dragon:'shadowball',dark:'shadowball',poison:'poisonwisp',fairy:'energyball',steel:'rock2',normal:'energyball',fighting:'energyball'}[move.type]||'energyball';
actor.face=dx>0?1:-1;actor.aura=c;actor.charge=true;view.announce(actor,move);log(`${title(actor.name)} uses ${title(move.name)} on ${title(target.name)}!`);audioEngine.sfx(move.type,'charge');const signature=['roar-of-time','precipice-blades','spacial-rend','dragon-ascent','shadow-force','hydro-pump'].includes(move.name);await w(signature?520:350);actor.charge=false;if(token!==runId)return;
if(dodge){view.move(target,{x:Math.max(70,Math.min(470,dest.x+(dest.x<270?45:-45))),y:dest.y+(target.team===0?-20:20)},180);}
if(physical){const contact={x:dest.x-nx*47,y:dest.y-ny*47};let style=move.fx;if(move.name==='crunch')style='bite';if(move.name==='close-combat')style='punch';if(move.name==='dragon-ascent')style='rush';if(move.name==='shadow-force'){actor.el.style.opacity='.05';await w(150);actor.pos={x:contact.x,y:contact.y};actor.el.style.opacity='1';}else await view.motion(actor,contact,move.fx==='rush'?280:360,w,move.name==='dragon-ascent'?100:move.fx==='kick'?32:10);if(token!==runId)return;if(['punch','kick','slash','tail','bite'].includes(style))view.addFx(style,actor.pos,dest,c,260);if(move.name==='close-combat'||move.fx==='kick'){view.addFx(style,actor.pos,{x:dest.x-14,y:dest.y+10},c,180);audioEngine.sfx('fighting','impact');await w(90);view.addFx(style,actor.pos,{x:dest.x+12,y:dest.y-5},c,200)}else if(style==='rush'){view.addFx('wave',source,contact,c,230,{asset});}}
else {const fx=move.fx==='burst'?'orb':move.fx;view.addFx(fx,source,dest,c,fx==='meteor'?780:fx==='ground'?720:620,{asset});await w(fx==='meteor'?640:fx==='ground'?560:450)}
if(token!==runId)return;if(dodge){view.damage(target,'DODGED');log(title(target.name)+' dodges!');}else if(mult===0){view.damage(target,'IMMUNE');log('It has no effect on '+title(target.name)+'.');}else{target.hp=Math.max(0,target.hp-damage);view.impact(target,c,crit||signature||target.hp===0);view.updateHP(target);view.damage(target,crit?'CRIT! −'+damage:'−'+damage,crit);audioEngine.sfx(move.type,'impact');if(target.hp>0)view.move(target,{x:Math.max(65,Math.min(475,dest.x+nx*20)),y:Math.max(195,Math.min(790,dest.y+ny*20))},100);log(`${damage} damage.${crit?' Critical hit!':''}${mult>1?' Super effective!':mult<1?' Not very effective.':''}`);if(mult>1)view.message('Super effective!',350);if(crit)view.message('A critical hit!',420);}
await w(crit?280:140);if(token!==runId)return;view.label=null;if(physical)view.move(actor,{x:Math.max(75,Math.min(465,source.x+(visualRng()-.5)*24)),y:Math.max(actor.team===0?210:640,Math.min(actor.team===0?350:790,source.y+(visualRng()-.5)*16))},240);if(target.hp>0)view.move(target,{x:Math.max(75,Math.min(465,dest.x+(visualRng()-.5)*24)),y:Math.max(target.team===0?210:640,Math.min(target.team===0?350:790,dest.y+(visualRng()-.5)*16))},220);await w(320);if(token!==runId)return;if(target.hp<=0){view.message(title(target.name)+' fainted!',600);log(title(target.name)+' fainted!','ko');await w(600)}
}
function frame(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;if(!paused){view.cinematic=cinematic;view.draw(dt*speed);if(running)elapsed+=dt;if(cinematic&&arena==='volcano'&&Math.random()<dt*5)view.particles.push({x:30+Math.random()*480,y:940,vx:5,vy:-70,size:2,life:5,max:5,color:'#ffb15b'})}requestAnimationFrame(frame)}
$('#start').onclick=()=>start();$('#stage-start').onclick=()=>start();$('#rematch').onclick=()=>start();$('#replay').onclick=()=>start(true);$('#pause').onclick=()=>{if(!running)return;paused=!paused;$('#stage').classList.toggle('paused',paused);$('#pause').innerHTML=paused?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';$('#playback-label').textContent=paused?'The battle is paused':'The showdown is live';audioEngine.pause(paused)};
$('#stop').onclick=()=>{runId++;running=false;paused=false;audioEngine.pause(false);audioEngine.background(false);$('#stage').classList.remove('paused');resetPreview();lockUI();log('Battle stopped. Adjust your teams and start again.');};
$('#sound').onclick=async()=>{try{sound=!sound;if(sound){await audioEngine.enable();audioEngine.background(running&&!paused)}else audioEngine.disable();$('#sound span').textContent=sound?'ON':'OFF';$('#sound').setAttribute('aria-label',sound?'Mute battle sound':'Enable battle sound');}catch{sound=false;$('#playback-label').textContent='Audio unavailable. You can still watch the battle.'}};
$('#music').onchange=e=>{audioEngine.musicEnabled=e.target.checked;audioEngine.background(running&&!paused)};
$('#cinematic').checked=cinematic;$('#cinematic').onchange=e=>cinematic=e.target.checked;
$$('#speeds button').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);$$('#speeds button').forEach(x=>x.classList.toggle('selected',x===b))});
$$('.arena-option').forEach(b=>b.onclick=()=>{if(running)return;arena=b.dataset.arena;view.arena=arena;$$('.arena-option').forEach(x=>x.classList.toggle('selected',x===b));$('#arena-name').textContent=names[arena];$('#weather').textContent=arena==='volcano'?'✦ FALLING EMBERS':arena==='forest'?'✦ DAPPLED SUNLIGHT':'✦ CLEAR SKIES';view.drawArena()});
$('#shuffle').onclick=()=>{if(running)return;const ids=[...featured];for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}teams=[ids.slice(0,3),ids.slice(3,6)];renderTeams();saveTeams();resetPreview()};
$('#close-picker').onclick=()=>$('#picker').close();$('#search').oninput=()=>{limit=60;renderPicker()};$$('.picker-filters button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;limit=60;$$('.picker-filters button').forEach(x=>x.classList.toggle('selected',x===b));renderPicker()});$('#more').onclick=()=>{limit+=60;renderPicker()};
function clean(on){document.body.classList.toggle('clean-mode',on);$('#clean').textContent=on?'↙ Exit clean view':'▣ Clean 9:16 view';$('#clean').setAttribute('aria-pressed',String(on));}$('#clean').onclick=()=>clean(!document.body.classList.contains('clean-mode'));document.addEventListener('keydown',e=>{if(e.key==='Escape')clean(false)});
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.theater').requestFullscreen()}catch{$('#playback-label').textContent='Fullscreen is unavailable in this browser'}};
$('#credits').onclick=()=>$('#credits-dialog').showModal();$('.dialog-close').onclick=()=>$('#credits-dialog').close();
async function init(){try{[cache,roster]=await Promise.all([fetch('pokemon.json').then(r=>r.json()),fetch('roster.json').then(r=>r.json())]);try{const saved=JSON.parse(localStorage.getItem('bt-teams'));if(saved?.length===2&&saved.every(t=>t.length===3&&t.every(id=>Number.isInteger(id)&&id>=1&&id<=1025))){await Promise.all(saved.flat().map(data));teams=saved}}catch{}renderTeams();resetPreview();view.drawArena();lockUI();requestAnimationFrame(frame)}catch(e){$('#playback-label').textContent='Could not load battle data. Refresh to retry.';$('#start').disabled=true;$('#stage-start').disabled=true;console.error(e)}}
init();
